from typing import List

class SolutionRecursive:
    def maxProfit(self, prices: List[int]) -> int:
        def dfs(i: int, holding: bool) -> int:
            if i >= len(prices):
                return 0
            if holding:
                sell = prices[i] + dfs(i + 2, False)
                keep = dfs(i + 1, True)
                return max(sell, keep)
            buy = -prices[i] + dfs(i + 1, True)
            skip = dfs(i + 1, False)
            return max(buy, skip)

        return dfs(0, False)

